import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CuR1irRm.js";var i=JSON.parse(`{"title":"Go Clean Architecture + CQRS","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/go-clean-architecture.md","filePath":"conventions/go-clean-architecture.md"}`),a={name:`conventions/go-clean-architecture.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1794111317000`},[...i[0]||=[e(`<h1 id="go-clean-architecture-cqrs" tabindex="-1">Go Clean Architecture + CQRS <a class="header-anchor" href="#go-clean-architecture-cqrs" aria-label="Permalink to “Go Clean Architecture + CQRS”">​</a></h1><p>Rules for every Go service (<code>internal/{service}</code>). Reference implementation: <code>internal/note</code>.</p><h2 id="layers-and-dependency-direction" tabindex="-1">Layers and dependency direction <a class="header-anchor" href="#layers-and-dependency-direction" aria-label="Permalink to “Layers and dependency direction”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span>controller ─► app ─► domain ◄─ infra</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th><th>May import</th></tr></thead><tbody><tr><td><code>domain/</code></td><td>Aggregates, value objects, domain events, repo + UoW interfaces</td><td>stdlib only</td></tr><tr><td><code>app/</code></td><td>Commands, queries, app models, ports (read models, outbound svcs)</td><td><code>domain</code></td></tr><tr><td><code>infra/</code></td><td>Adapters: postgres, kafka, grpc clients, payment providers</td><td><code>domain</code>, <code>app</code></td></tr><tr><td><code>controller/</code></td><td>http, grpc, event, cron: translate and delegate, never decide</td><td><code>app</code> only, <strong>never <code>domain</code></strong></td></tr><tr><td><code>component/</code></td><td>Cross-cutting config: event topics (all of them), validator</td><td>as needed</td></tr></tbody></table><p><code>domain</code> and <code>app</code> never import <code>infra</code> or <code>controller</code>. Wiring (google/wire) is the only place that joins them.</p><h2 id="cqrs-split" tabindex="-1">CQRS split <a class="header-anchor" href="#cqrs-split" aria-label="Permalink to “CQRS split”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Command (write)</th><th>Query (read)</th></tr></thead><tbody><tr><td>App file</td><td><code>cmd_*.go</code>, <code>commonhandler.Cmd[T]</code></td><td><code>q_*.go</code>, <code>commonhandler.Query[Q, R]</code></td></tr><tr><td>Returns</td><td><strong><code>error</code> only</strong>, no result, no domain model</td><td><strong>app model only</strong>, never a domain model</td></tr><tr><td>Goes through</td><td><code>domain.UnitOfWork</code> → aggregate → repo</td><td>an <code>app</code> read-model port, bypasses aggregates</td></tr><tr><td>Port impl</td><td><code>infra/persistence/pgrepo</code></td><td><code>infra/persistence/pgreadmodel</code></td></tr><tr><td>SQL (<code>pgsqlc/</code>)</td><td><code>&lt;aggregate&gt;.sql</code>, locks via <code>for_update</code></td><td><code>&lt;aggregate&gt;_read.sql</code>, <code>Read…</code> names, never locks</td></tr><tr><td>Transaction</td><td><code>uow.Execute</code> owns it, never in a handler</td><td>none</td></tr></tbody></table><ul><li>Write and read SQL are separate files and separate queries even when they look identical.</li><li>A command needing an id for its response gets it from the controller (<code>ID</code> input), and the controller then answers with a query. Commands never &quot;return&quot; through a field on the struct.</li><li>Something that must hand back a value (e.g. a provider session URL) is modeled as a query.</li><li>Lock-aware lookups use one query with <code>FOR UPDATE -- :if @for_update</code> (sqlc dynamic filter), not a <code>Get</code>/<code>GetForUpdate</code> pair.</li></ul><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to “Models”">​</a></h2><ul><li><strong>Domain model</strong>: unexported fields, <code>NewX</code> (validates, emits events) / <code>UnmarshalX</code> (rehydrate, no validation). Mutators call <code>addEvent</code>; the repo <code>Save</code> drains events. Domain enums are <code>uint8</code> <code>iota</code> types with <code>IsValid()</code> and <code>String()</code>.</li><li><strong>App model</strong> (<code>app/model.go</code>): plain exported structs and its own enums. It <strong>never embeds or aliases a domain type</strong> and may diverge from the aggregate. It is the only shape that leaves <code>app</code> (query results, command inputs).</li><li>Domain ↔ app conversion lives in <code>app/mapper.go</code> only, with explicit switches per enum. Handlers map domain → app on the way out and app → domain on the way in.</li><li>A read-model port may return domain aggregates when the handler must run domain rules on them (e.g. resolving entitlements). They are converted before the handler returns.</li></ul><h2 id="mapping-at-every-boundary" tabindex="-1">Mapping at every boundary <a class="header-anchor" href="#mapping-at-every-boundary" aria-label="Permalink to “Mapping at every boundary”">​</a></h2><p>Each boundary has its own types and an explicit mapper; never reuse a wire type across layers.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>Mapper</th></tr></thead><tbody><tr><td>HTTP/gRPC request → command</td><td><code>controller/*/mapin.go</code>: wire → <strong>app</strong> types</td></tr><tr><td>query result → response</td><td><code>controller/*/mapout.go</code>: <strong>app</strong> → wire types</td></tr><tr><td>SQL row ↔ domain</td><td><code>infra/persistence/pgmapper</code>, shared by <code>pgrepo</code> and <code>pgreadmodel</code></td></tr><tr><td>SQL enum / jsonb</td><td>sqlc <code>overrides</code> (typed columns), <code>pgmapper</code> for enums</td></tr><tr><td>domain/app → integration event</td><td><code>infra</code> publisher, payload types from <code>api/share</code></td></tr></tbody></table><h2 id="sqlc" tabindex="-1">sqlc <a class="header-anchor" href="#sqlc" aria-label="Permalink to “sqlc”">​</a></h2><ul><li>Use <code>sqlc.arg(&#39;name&#39;)</code> / <code>sqlc.narg(&#39;name&#39;)</code>, never <code>$1</code>. Param names match column names.</li><li>Runtime-optional filters use the dynamic-filter plugin (<code>-- :if @param</code>), see <code>note_read.sql</code>.</li><li>Generated <code>pgsqlc</code> package is shared by <code>pgrepo</code> and <code>pgreadmodel</code>; neither exposes sqlc types outside <code>infra</code>.</li></ul><h2 id="events-and-topics" tabindex="-1">Events and topics <a class="header-anchor" href="#events-and-topics" aria-label="Permalink to “Events and topics”">​</a></h2><ul><li>All topics (published and consumed) are constants in <code>component/eventtopic.go</code>; never inline a topic string. Payload types are defined once in <code>api/share</code>.</li><li>Domain events are drained in repo <code>Save</code>; integration events go through the transactional outbox.</li><li>Notifications that must not fail the request are published after <code>uow.Execute</code> returns.</li></ul><h2 id="checklist-for-a-new-use-case" tabindex="-1">Checklist for a new use case <a class="header-anchor" href="#checklist-for-a-new-use-case" aria-label="Permalink to “Checklist for a new use case”">​</a></h2><ol><li>Domain method + event (writes only).</li><li><code>app/model.go</code> types it needs, <code>app/mapper.go</code> conversions.</li><li><code>cmd_*.go</code> or <code>q_*.go</code> (+ read-model port method for queries), register in <code>app.go</code> and <code>wire.go</code>.</li><li>SQL in the matching write or <code>_read</code> file, then <code>nx run {service}:gen:sqlc</code>.</li><li>API spec first (<code>api/</code>, <code>proto/</code>), then <code>nx gen api</code> / <code>nx gen proto</code>; controller mapin/mapout.</li><li><code>nx wire {service}</code>, <code>nx lint {service}</code>.</li></ol>`,20)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};